void WebManager::startAP(const String& ssid, const String& password)
{
    Serial.println();
    Serial.println("Starting Access Point...");

    WiFi.mode(WIFI_AP);

    if( WiFi.softAP(ssid.c_str(), password.c_str()) )
    {
        server.begin();

        Serial.println("Webserver started.");
           
        apRunning = true;

        Serial.print("SSID : "); Serial.println(ssid);
        Serial.print("IP   : "); Serial.println(WiFi.softAPIP());
    }
    else
    {
        apRunning = false;

        Serial.println("Starting Access Point failed.");
    }
    
}

void WebManager::stopAP()
{
    WiFi.softAPdisconnect(true);
    apRunning = false;

}

void WebManager::startSTA()
{
    WiFi.mode(WIFI_STA);

    server.begin();
    apRunning = false;

}

bool WebManager::isAPRunning()
{
    return apRunning;
    
}

IPAddress WebManager::getAPIP()
{
    return WiFi.softAPIP();
    
}

String WebManager::buildConfigJson()
{
    JsonDocument doc;

    doc["ssid"]     = configManager->cfg.ssid;
    doc["callsign"] = configManager->cfg.callsign;
    doc["host"]     = configManager->cfg.host;
    doc["port"]     = configManager->cfg.port;

    String result;

    serializeJson(doc, result);
    return result;
    
}

String WebManager::buildStatusJson()
{
    JsonDocument doc;

    doc["wifi"]  = (WiFi.status() == WL_CONNECTED);
    doc["ap"]    = apRunning;
    doc["ip"]    = WiFi.localIP().toString();
    doc["ap_ip"] = WiFi.softAPIP().toString();

    String result;

    serializeJson(doc, result);
    return result;

}

void WebManager::registerStaticContent()
{
    server.serveStatic("/", LittleFS, "/").setDefaultFile("index.html");

}

void WebManager::registerAPI()
{
	
	server.on(
        "/api/config",
        HTTP_GET,
        [this]
        (
            AsyncWebServerRequest*
            request
        )
        {
            request->send(
                200,
                "application/json",
                buildConfigJson()
            );
        }
    );
	
	server.on(
        "/api/status",
        HTTP_GET,
        [this]
        (
            AsyncWebServerRequest*
            request
        )
        {
            request->send(
                200,
                "application/json",
                buildStatusJson()
            );
        }
    );

    server.on(
        "/api/reset",
        HTTP_POST,
        [this]
        (
            AsyncWebServerRequest*
            request
        )
        {
            configManager->reset();

            request->send(
                200,
                "text/plain",
                "OK"
            );

            delay(1000);

            ESP.restart();
        }
    );

    server.on(
        "/api/whitelist",
        HTTP_GET,
        [this]
        (
            AsyncWebServerRequest* request
        )
        {
            if( !LittleFS.exists("/whitelist.json") )
            {
                request->send(
                    404,
                    "text/plain",
                    "whitelist.json not found"
                );
    
                return;
            }
    
            request->send(
                LittleFS,
                "/whitelist.json",
                "application/json",
                true
            );
        }
    );

    server.on(
        "/api/whitelist",
        HTTP_POST,
        [this]
        (
            AsyncWebServerRequest*
            request
        )
        {
            request->send(
                200,
                "application/json",
                "{\"result\":\"ok\"}"
            );
        },
        [this]
        (
            AsyncWebServerRequest *request,
            String filename,
            size_t index,
            uint8_t *data,
            size_t len,
            bool final
        )
        {
            static File uploadFile;
    
            if(index == 0)
            {
                Serial.println("Upload 'whitelist.json.'");
                uploadFile = LittleFS.open("/whitelist.json", "w");
            }
    
            if( uploadFile )
            {
                uploadFile.write(data, len);
            }
    
            if( final )
            {
                if( uploadFile )
                {
                    uploadFile.close();
                }
    
                Serial.println("Whitelist saved.");

                // Reload whitelist
                if( whitelist )
                {
                    whitelist->load();
                    Serial.println("Whitelist reloaded.");
                }

                // Reload whitelist size
                if( display )
                {
                    display->setWhitelistCount(whitelist->size());
                    Serial.println("Whitelist size reloaded.");
                }
            }
        }
    );

	 AsyncCallbackJsonWebHandler*
        handler =
            new AsyncCallbackJsonWebHandler(
                "/api/config",

                [this]
                (
                    AsyncWebServerRequest*
                    request,
                    JsonVariant&
                    json
                )
                {
                    JsonObject obj =
                        json.as<JsonObject>();

                    configManager->cfg.ssid =
                        obj["ssid"] |
                        "";

                    configManager->cfg.password =
                        obj["password"] |
                        "";

                    configManager->cfg.callsign =
                        obj["callsign"] |
                        "";

                    configManager->cfg.authkey =
                        obj["authkey"] |
                        "";

                    configManager->cfg.host =
                        obj["host"] |
                        DEFAULT_DAPNET_HOST;

                    configManager->cfg.port =
                        obj["port"] |
                        DEFAULT_DAPNET_PORT;

                    configManager->save();

                    request->send(
                        200,
                        "application/json",
                        "{\"result\":\"ok\"}"
                    );

                    delay(1000);

                    ESP.restart();
                }
            );

    server.addHandler(
        handler
    );

}

void WebManager::registerNotFound()
{
    server.onNotFound(
        []
        (
            AsyncWebServerRequest*
            request
        )
        {
            request->send(
                404,
                "text/plain",
                "404 Not Found"
            );
        }
    );
    
}

void WebManager::registerRoutes()
{
    registerStaticContent();
    registerAPI();
    registerNotFound();

}
